                    <button data-testid="volume-name-cancel" @click="cancelEditingName()" tw-class="p-1 text-gray-400 hover:text-gray-600 shrink-0" :title="lazyStrings.volumes__cancel()"><XIcon tw-class="w-3.5 h-3.5" /></button>
