                  <div v-if="getMount({ volId: volume.id })?.readOnly" tw-class="flex items-center gap-1 px-1.5 py-0.5 rounded bg-green-50 dark:bg-green-900/20 text-green-600 dark:text-green-400 border border-green-100 dark:border-green-900/30" :title="lazyStrings.volumes__read_only()">
                    <LockIcon tw-class="w-2.5 h-2.5" />
                    <span tw-class="text-[9px] font-bold uppercase tracking-tight">{{ lazyStrings.volumes__read_only() }}</span>
