                  <span tw-class="text-[10px] text-gray-400 font-medium hidden sm:inline">·</span>
                  <span tw-class="text-[10px] text-gray-400 font-medium">{{ volume.type === 'host' ? lazyStrings.volumes__linked() : lazyStrings.volumes__copied() }}</span>
                </div>
              </div>
            </div>

            <div tw-class="flex items-center gap-1 shrink-0">
              <button
