                @click="startEditing({ volume })"
                tw-class="p-2 text-gray-400 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded-xl transition-colors"
                :title="lazyStrings.volumes__configure()"
