          <div v-if="editingMountId === volume.id" tw-class="px-4 pb-4 pt-2 border-t border-gray-50 dark:border-gray-700/50 bg-gray-50/30 dark:bg-gray-900/10 rounded-b-2xl overflow-hidden">
            <div tw-class="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div tw-class="space-y-1.5">
                <label tw-class="text-[10px] font-bold text-gray-400 uppercase tracking-tighter">{{ lazyStrings.volumes__path() }}</label>
                <input
