                  placeholder="/mnt/folder"
                />
              </div>
              <div tw-class="space-y-1.5">
                <label tw-class="text-[10px] font-bold text-gray-400 uppercase tracking-tighter">{{ lazyStrings.volumes__access_mode() }}</label>
                <div tw-class="flex gap-2">
                  <button
