                    :tw-class="['flex-1 flex items-center justify-center gap-2 px-3 py-1.5 rounded-lg text-[10px] font-bold transition-all border', editForm.readOnly ? 'bg-gray-100 dark:bg-gray-700 border-gray-200 dark:border-gray-600 text-gray-800 dark:text-white' : 'bg-white dark:bg-gray-800 border-gray-100 dark:border-gray-800 text-gray-400']"
                  >
                    <LockIcon tw-class="w-3 h-3" />
                    {{ lazyStrings.volumes__read_only() }}
                  </button>
                  <button
                    @click="editForm.readOnly = false"
                    :tw-class="['flex-1 flex items-center justify-center gap-2 px-3 py-1.5 rounded-lg text-[10px] font-bold transition-all border', !editForm.readOnly ? 'bg-blue-50 dark:bg-blue-900/20 border-blue-200 dark:border-blue-800 text-blue-600 dark:text-blue-400' : 'bg-white dark:bg-gray-800 border-gray-100 dark:border-gray-800 text-gray-400']"
                  >
                    <UnlockIcon tw-class="w-3 h-3" />
                    {{ lazyStrings.volumes__read_write() }}
                  </button>
                </div>
              </div>
            </div>
            <div tw-class="flex justify-end gap-2 mt-4">
              <button @click="editingMountId = null" tw-class="px-3 py-1.5 text-[10px] font-bold text-gray-400 hover:text-gray-600">{{ lazyStrings.volumes__cancel() }}</button>
              <button
                data-testid="mount-save-btn"
                @click="saveMountSettings({ volId: volume.id })"
                tw-class="flex items-center gap-2 px-4 py-1.5 bg-blue-600 text-white rounded-lg text-[10px] font-bold hover:bg-blue-700 shadow-sm"
              >
                <CheckIcon tw-class="w-3 h-3" />
                {{ lazyStrings.volumes__save_changes() }}
              </button>
            </div>
          </div>
        </div>
      </div>
    </section>

    <!-- Unmounted section -->
    <section v-if="unmountedVolumes.length > 0" tw-class="space-y-4">
      <h3 tw-class="text-[10px] font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest px-1">
